# RWDM_LOCK: Lock, Unlock: locked objects cannot be selected. The script rwdm_lock_script.txt is generated by rwdm_gen.py. The oracle is exact set logic on four Point objects (ids 1..4 at x = 1..4):
# each step lists the objects that a SelAll (or the current selection) reaches, and the ids must equal the expected set exactly (and the count line must agree).
if [ -n "${DISPLAY:-}" ] && xset q >/dev/null 2>&1 || ! command -v xvfb-run >/dev/null 2>&1; then
  RWDM_LOCK_OUT="$(timeout 900 "$BIN" --smoke 60 --script "$HERE/rwdm_lock_script.txt" 2>&1)" || { echo "$RWDM_LOCK_OUT" | tail -40; echo "FAIL RWDM_LOCK_run: script exited non-zero"; fail=1; RWDM_LOCK_OUT=""; }
else
  RWDM_LOCK_OUT="$(timeout 900 xvfb-run -a -s "-screen 0 1600x900x24" "$BIN" --smoke 60 --script "$HERE/rwdm_lock_script.txt" 2>&1)" || { echo "$RWDM_LOCK_OUT" | tail -40; echo "FAIL RWDM_LOCK_run: script exited non-zero"; fail=1; RWDM_LOCK_OUT=""; }
fi
rwdm_lock_block() { awk -v name="$1" '$0 ~ ("Unknown command: RWDMBEGIN_" name "$") { on = 1; next } on && /Unknown command: RWDMBEGIN_/ { exit } on { print }' <<<"$RWDM_LOCK_OUT"; }
# rwdm_lock_ids STEP EXPECTED_IDS COUNT_LINE_OR_NONE DESC: the ids listed in the step, in order, are exactly EXPECTED_IDS ("-" = none); COUNT: the "N object(s) selected" line must say N
rwdm_lock_ids() {
  local blk got cnt; blk="$(rwdm_lock_block "$1")"
  got="$({ grep -oE '^history: Object [0-9]+ ' <<<"$blk" || true; } | sed -E 's/^history: Object ([0-9]+) /\1/' | tr '\n' ' ' | sed 's/ $//')"; [ -n "$got" ] || got="-"
  cnt="$({ grep -oE '^history: [0-9]+ object\(s\) selected' <<<"$blk" || true; } | tail -1 | sed -E 's/^history: ([0-9]+) .*/\1/')"
  if [ "$got" = "$2" ] && { [ "$3" = none ] || [ "$cnt" = "$3" ]; }; then echo "ok   RWDM_LOCK_$1: $4 (ids: $got)"
  else echo "FAIL RWDM_LOCK_$1: $4 (listed ids '$got', expected '$2'; selected-count line '${cnt:-none}', expected '$3')"; fail=1; fi
}
rwdm_lock_ids lock "3 4" 2 "after Lock of 1 and 2 a SelAll reaches only 3 and 4 (locked objects cannot be selected)"
rwdm_lock_ids locked_by_id "-" none "SelID of a locked object selects nothing (it cannot be selected by id either)"
rwdm_lock_ids unlock "1 2 3 4" 4 "Unlock makes every locked object selectable again: all four"
